import{_ as e,o as s,c as i,ag as n}from"./chunks/framework.wGDfT7ie.js";const u=JSON.parse('{"title":"Privacy Features Guide","description":"","frontmatter":{},"headers":[],"relativePath":"privacy-features.md","filePath":"privacy-features.md"}'),t={name:"privacy-features.md"};function l(o,a,r,p,c,d){return s(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="privacy-features-guide" tabindex="-1">Privacy Features Guide <a class="header-anchor" href="#privacy-features-guide" aria-label="Permalink to &quot;Privacy Features Guide&quot;">​</a></h1><p>This guide covers zkde.fi&#39;s privacy features in detail, with practical examples and use cases.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>zkde.fi provides three layers of privacy:</p><ol><li><strong>Confidential Transfers</strong> — Hide amounts on deposits and withdrawals</li><li><strong>Selective Disclosure</strong> — Prove statements without revealing data</li><li><strong>Position Aggregation</strong> — Prove total value without revealing breakdown</li></ol><hr><h2 id="_1-confidential-transfers" tabindex="-1">1. Confidential Transfers <a class="header-anchor" href="#_1-confidential-transfers" aria-label="Permalink to &quot;1. Confidential Transfers&quot;">​</a></h2><h3 id="private-deposits" tabindex="-1">Private Deposits <a class="header-anchor" href="#private-deposits" aria-label="Permalink to &quot;Private Deposits&quot;">​</a></h3><p>When you make a private deposit, the amount is hidden using a cryptographic commitment.</p><p><strong>How it works:</strong></p><ol><li>Enter the amount you want to deposit</li><li>zkde.fi generates a commitment: <code>commitment = hash(amount, nonce)</code></li><li>Only the commitment is stored on-chain — not the amount</li><li>You keep the nonce privately to later prove ownership</li></ol><p><strong>What&#39;s visible on-chain:</strong></p><ul><li>Commitment hash (visible)</li><li>Amount (hidden)</li><li>Your balance (hidden)</li></ul><p><strong>Example:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User deposits 1000 USDC privately</span></span>
<span class="line"><span></span></span>
<span class="line"><span>On-chain record:</span></span>
<span class="line"><span>  commitment: 0x7a8b9c...</span></span>
<span class="line"><span>  amount: (hidden)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Only the user knows:</span></span>
<span class="line"><span>  amount: 1000 USDC</span></span>
<span class="line"><span>  nonce: 0x123456...</span></span></code></pre></div><h3 id="private-withdrawals" tabindex="-1">Private Withdrawals <a class="header-anchor" href="#private-withdrawals" aria-label="Permalink to &quot;Private Withdrawals&quot;">​</a></h3><p>To withdraw from a private commitment:</p><ol><li><strong>Select a commitment</strong> — Choose from your list of commitments</li><li><strong>Enter withdrawal amount</strong> — Must be &lt;= commitment balance</li><li><strong>Generate proof</strong> — Proves ownership and sufficient balance</li><li><strong>Nullifier creation</strong> — Prevents double-spend</li></ol><p><strong>What&#39;s visible on-chain:</strong></p><ul><li>Nullifier (visible, prevents reuse)</li><li>Commitment being spent (visible)</li><li>Withdrawal amount (hidden)</li><li>Remaining balance (hidden)</li></ul><p><strong>Example:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User withdraws 300 USDC from commitment 0x7a8b9c...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>On-chain record:</span></span>
<span class="line"><span>  nullifier: 0xdef123...</span></span>
<span class="line"><span>  commitment: 0x7a8b9c...</span></span>
<span class="line"><span>  amount: (hidden)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The nullifier ensures this commitment portion can&#39;t be spent again.</span></span></code></pre></div><hr><h2 id="_2-selective-disclosure" tabindex="-1">2. Selective Disclosure <a class="header-anchor" href="#_2-selective-disclosure" aria-label="Permalink to &quot;2. Selective Disclosure&quot;">​</a></h2><p>Prove statements about your portfolio without revealing the underlying data.</p><h3 id="available-statement-types" tabindex="-1">Available Statement Types <a class="header-anchor" href="#available-statement-types" aria-label="Permalink to &quot;Available Statement Types&quot;">​</a></h3><h4 id="yield-above-threshold" tabindex="-1">Yield Above Threshold <a class="header-anchor" href="#yield-above-threshold" aria-label="Permalink to &quot;Yield Above Threshold&quot;">​</a></h4><p>Prove your yield exceeds a value.</p><p><strong>Use cases:</strong></p><ul><li>Access yield-based protocol tiers</li><li>Prove performance to investors</li><li>Qualify for rewards programs</li></ul><p><strong>Example:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Statement: &quot;My 30-day yield &gt; 10%&quot;</span></span>
<span class="line"><span>Proof registered on-chain</span></span>
<span class="line"><span>Actual yield (15.7%) remains private</span></span></code></pre></div><h4 id="balance-above-threshold" tabindex="-1">Balance Above Threshold <a class="header-anchor" href="#balance-above-threshold" aria-label="Permalink to &quot;Balance Above Threshold&quot;">​</a></h4><p>Prove your balance exceeds a value.</p><p><strong>Use cases:</strong></p><ul><li>Access balance-gated features</li><li>Prove solvency to lenders</li><li>Qualify for premium tiers</li></ul><h4 id="risk-compliance" tabindex="-1">Risk Compliance <a class="header-anchor" href="#risk-compliance" aria-label="Permalink to &quot;Risk Compliance&quot;">​</a></h4><p>Prove your portfolio risk is below a threshold.</p><p><strong>Supported metrics:</strong></p><ul><li><strong>Value at Risk (VaR)</strong> — Maximum expected loss</li><li><strong>Sharpe Ratio</strong> — Risk-adjusted returns</li><li><strong>Max Drawdown</strong> — Largest peak-to-trough decline</li></ul><p><strong>Use cases:</strong></p><ul><li>Meet institutional risk limits</li><li>Prove conservative strategy</li><li>Regulatory compliance</li></ul><p><strong>Example:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Statement: &quot;Portfolio VaR &lt; 20%&quot;</span></span>
<span class="line"><span>Proof: Verified</span></span>
<span class="line"><span>Actual risk profile remains private</span></span></code></pre></div><h4 id="performance-proofs" tabindex="-1">Performance Proofs <a class="header-anchor" href="#performance-proofs" aria-label="Permalink to &quot;Performance Proofs&quot;">​</a></h4><p>Prove your APY exceeded a threshold over a period.</p><p><strong>Use cases:</strong></p><ul><li>Qualify for advanced protocol features</li><li>Demonstrate trading skill</li><li>Access professional tools</li></ul><p><strong>Example:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Statement: &quot;30-day APY &gt; 15%&quot;</span></span>
<span class="line"><span>Proof: Verified</span></span>
<span class="line"><span>Actual APY and trades remain private</span></span></code></pre></div><h4 id="kyc-eligibility" tabindex="-1">KYC Eligibility <a class="header-anchor" href="#kyc-eligibility" aria-label="Permalink to &quot;KYC Eligibility&quot;">​</a></h4><p>Prove financial standing for regulatory compliance.</p><p><strong>Use cases:</strong></p><ul><li>Accredited investor verification</li><li>Regulatory compliance</li><li>Access to restricted protocols</li></ul><p><strong>Example:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Statement: &quot;Total holdings &gt; $100,000&quot;</span></span>
<span class="line"><span>Proof: Verified</span></span>
<span class="line"><span>Exact holdings remain private</span></span></code></pre></div><h4 id="portfolio-aggregation" tabindex="-1">Portfolio Aggregation <a class="header-anchor" href="#portfolio-aggregation" aria-label="Permalink to &quot;Portfolio Aggregation&quot;">​</a></h4><p>Prove total value across protocols without revealing breakdown.</p><p><strong>Use cases:</strong></p><ul><li>Prove total value for protocol access</li><li>Multi-protocol tier qualification</li><li>Privacy-preserving wealth attestation</li></ul><p><strong>Example:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Statement: &quot;Total across Ekubo + JediSwap + Private &gt; $50,000&quot;</span></span>
<span class="line"><span>Proof: Verified</span></span>
<span class="line"><span>Individual protocol amounts remain private</span></span></code></pre></div><hr><h2 id="_3-position-aggregation" tabindex="-1">3. Position Aggregation <a class="header-anchor" href="#_3-position-aggregation" aria-label="Permalink to &quot;3. Position Aggregation&quot;">​</a></h2><p>The portfolio view supports a privacy toggle:</p><h3 id="public-view" tabindex="-1">Public View <a class="header-anchor" href="#public-view" aria-label="Permalink to &quot;Public View&quot;">​</a></h3><ul><li>Shows pie chart with protocol breakdown</li><li>Displays individual protocol amounts</li><li>Full allocation visibility</li></ul><h3 id="private-view" tabindex="-1">Private View <a class="header-anchor" href="#private-view" aria-label="Permalink to &quot;Private View&quot;">​</a></h3><ul><li>Shows only total aggregated value</li><li>Displays count of positions (not amounts)</li><li>No breakdown visible</li><li>&quot;Generate Aggregation Proof&quot; button</li></ul><p><strong>When to use Private View:</strong></p><ul><li>Sharing screen with others</li><li>Demonstrating total value without strategy</li><li>Regulatory attestations</li></ul><hr><h2 id="privacy-architecture" tabindex="-1">Privacy Architecture <a class="header-anchor" href="#privacy-architecture" aria-label="Permalink to &quot;Privacy Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    Frontend                              │</span></span>
<span class="line"><span>│  ┌───────────────┐  ┌───────────────┐  ┌─────────────┐ │</span></span>
<span class="line"><span>│  │ Private       │  │ Selective     │  │ Position    │ │</span></span>
<span class="line"><span>│  │ Transfer      │  │ Disclosure    │  │ Chart       │ │</span></span>
<span class="line"><span>│  │ Panel         │  │ Panel         │  │ (Toggle)    │ │</span></span>
<span class="line"><span>│  └───────┬───────┘  └───────┬───────┘  └──────┬──────┘ │</span></span>
<span class="line"><span>└──────────┼──────────────────┼─────────────────┼────────┘</span></span>
<span class="line"><span>           │                  │                 │</span></span>
<span class="line"><span>           ▼                  ▼                 ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    Backend API                           │</span></span>
<span class="line"><span>│  /private_deposit    /disclosure/risk    /position/     │</span></span>
<span class="line"><span>│  /private_withdraw   /disclosure/perf    aggregate      │</span></span>
<span class="line"><span>│  /private_commitments                                   │</span></span>
<span class="line"><span>└──────────────────────────┬──────────────────────────────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>                           ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                 Starknet Contracts                       │</span></span>
<span class="line"><span>│  ┌─────────────────┐  ┌────────────────┐               │</span></span>
<span class="line"><span>│  │ Confidential    │  │ Selective      │               │</span></span>
<span class="line"><span>│  │ Transfer        │  │ Disclosure     │               │</span></span>
<span class="line"><span>│  │ (Garaga)        │  │ (Integrity)    │               │</span></span>
<span class="line"><span>│  └─────────────────┘  └────────────────┘               │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><h3 id="for-maximum-privacy" tabindex="-1">For Maximum Privacy <a class="header-anchor" href="#for-maximum-privacy" aria-label="Permalink to &quot;For Maximum Privacy&quot;">​</a></h3><ol><li><strong>Use private deposits</strong> for all sensitive amounts</li><li><strong>Enable privacy mode</strong> in portfolio view when sharing</li><li><strong>Use selective disclosure</strong> instead of revealing actual values</li><li><strong>Generate proofs</strong> for third-party verification</li></ol><h3 id="for-compliance" tabindex="-1">For Compliance <a class="header-anchor" href="#for-compliance" aria-label="Permalink to &quot;For Compliance&quot;">​</a></h3><ol><li><strong>Register disclosures on-chain</strong> for audit trail</li><li><strong>Use KYC eligibility proofs</strong> for regulated access</li><li><strong>Generate risk compliance proofs</strong> for institutional requirements</li><li><strong>Keep shareable proof links</strong> for verifiers</li></ol><h3 id="for-defi-operations" tabindex="-1">For DeFi Operations <a class="header-anchor" href="#for-defi-operations" aria-label="Permalink to &quot;For DeFi Operations&quot;">​</a></h3><ol><li><strong>Check commitment balances</strong> before withdrawing</li><li><strong>Store nonces securely</strong> — needed for withdrawals</li><li><strong>Use aggregation proofs</strong> for multi-protocol tier access</li><li><strong>Monitor nullifiers</strong> to track spent commitments</li></ol><hr><h2 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API Reference&quot;">​</a></h2><h3 id="private-transfers" tabindex="-1">Private Transfers <a class="header-anchor" href="#private-transfers" aria-label="Permalink to &quot;Private Transfers&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/zkdefi/private_deposit</span></span>
<span class="line"><span>POST /api/v1/zkdefi/private_withdraw</span></span>
<span class="line"><span>GET  /api/v1/zkdefi/private_commitments/{address}</span></span></code></pre></div><h3 id="selective-disclosure" tabindex="-1">Selective Disclosure <a class="header-anchor" href="#selective-disclosure" aria-label="Permalink to &quot;Selective Disclosure&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/zkdefi/disclosure/generate</span></span>
<span class="line"><span>POST /api/v1/zkdefi/disclosure/risk_compliance</span></span>
<span class="line"><span>POST /api/v1/zkdefi/disclosure/performance</span></span>
<span class="line"><span>POST /api/v1/zkdefi/disclosure/kyc_eligibility</span></span>
<span class="line"><span>POST /api/v1/zkdefi/disclosure/aggregation</span></span></code></pre></div><h3 id="position-aggregation" tabindex="-1">Position Aggregation <a class="header-anchor" href="#position-aggregation" aria-label="Permalink to &quot;Position Aggregation&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/zkdefi/position/aggregate/{address}</span></span></code></pre></div><hr><p>Next: <a href="/docs/contracts.html">Contracts</a></p>`,92)])])}const g=e(t,[["render",l]]);export{u as __pageData,g as default};
